def conservar_lo_publicado(apps, schema_editor):
    """Lo que ya estaba publicado sigue publicado; los avisos existentes también."""
    for modelo in ("Documento", "Evento"):
        Modelo = apps.get_model("contenido", modelo)
        Modelo.objects.filter(publicado=True).update(estado="publicada")
    apps.get_model("contenido", "Aviso").objects.update(estado="publicada")


def restaurar_publicado(apps, schema_editor):
    for modelo in ("Documento", "Evento"):
        Modelo = apps.get_model("contenido", modelo)
        Modelo.objects.filter(estado="publicada").update(publicado=True)
        Modelo.objects.exclude(estado="publicada").update(publicado=False)


